require_once '../includes/auth.php';requireLogin();requireHostContext();$rows=[];$q=$conn->query("SHOW TABLES LIKE 'tenants'");if($q&&$q->num_rows){$r=$conn->query("SELECT * FROM tenants ORDER BY id DESC LIMIT 200");if($r)while($x=$r->fetch_assoc())$rows[]=$x;}
